// generated by muse-spark-1.3 in 10572 ms, attempts 1, valid true
const T = aide.THREE;
const BALL_R = 0.021;
const START = new T.Vector3(0, BALL_R, 0.15);
const HOLES = [[0, -0.20], [-0.18, -0.18], [0.18, -0.22]];
let hole = 0;
let strokes = 0;
let totalStrokes = 0;
let aiming = null;
let sinkTimer = 0;

const cup = aide.spawn('cup', { position: [HOLES[0][0], 0, HOLES[0][1]], radius: 0.05, height: 0.06, color: '#f4f4f4' });
const flag = aide.spawn('label', { text: 'Hole 1 of 3', position: [HOLES[0][0], 0.16, HOLES[0][1]], size: 0.03 });
const ball = aide.spawn('ball', { position: START, radius: BALL_R, color: '#ffffff', physics: { mass: 0.046, bounce: 0.15, friction: 0.7 } });
const aimLine = aide.spawn('line', { points: [START, START], color: '#ffd400', width: 0.005 });
const info = aide.spawn('label', { text: 'Strokes: 0', position: [0, 0.30, -0.05], size: 0.03 });

aide.say('Pinch the ball, pull back to aim, and let go to putt.');
aide.score(0);

aide.onPinch((e) => {
  if (e.object === ball && sinkTimer === 0 && ball.body.velocity.length() < 0.05) {
    aiming = { hand: e.hand, from: ball.position.clone() };
  }
});

const pull = new T.Vector3();
const tip = new T.Vector3();
function resetBall() {
  ball.position.copy(START);
  ball.body.velocity.set(0, 0, 0);
  ball.body.angularVelocity.set(0, 0, 0);
}

aide.onFrame((dt) => {
  if (sinkTimer > 0) {
    sinkTimer -= dt;
    if (sinkTimer <= 0) {
      sinkTimer = 0;
      hole += 1;
      if (hole >= HOLES.length) {
        flag.setText('Done: ' + totalStrokes);
        info.setText('Total: ' + totalStrokes);
        aide.say('All three holes done in ' + totalStrokes + ' strokes.');
        aide.done('mini golf finished, total ' + totalStrokes + ' strokes over 3 holes');
        return;
      }
      cup.position.set(HOLES[hole][0], 0, HOLES[hole][1]);
      flag.position.set(HOLES[hole][0], 0.16, HOLES[hole][1]);
      flag.setText('Hole ' + (hole + 1) + ' of 3');
      strokes = 0;
      info.setText('Strokes: 0');
      resetBall();
    }
    return;
  }
  if (aiming) {
    const h = aide.hands[aiming.hand];
    pull.copy(aiming.from).sub(h.pinchPoint);
    pull.y = 0;
    if (pull.length() > 0.2) pull.setLength(0.2);
    tip.copy(ball.position).addScaledVector(pull, 2);
    aimLine.setPoints([ball.position.clone(), tip.clone()]);
    if (!h.visible || !h.pinching) {
      if (pull.length() > 0.015) {
        ball.body.velocity.copy(pull).multiplyScalar(7);
        ball.body.velocity.y = 0;
        strokes += 1;
        info.setText('Strokes: ' + strokes);
      }
      aimLine.setPoints([START, START]);
      aiming = null;
    }
  }
  if (cup.contains(ball.position)) {
    totalStrokes += strokes;
    aide.score(totalStrokes);
    aide.spawn('burst', { position: [cup.position.x, 0.06, cup.position.z], color: '#ffd400' });
    if (strokes === 1) aide.say('Hole in one! Amazing.');
    else aide.say('Sunk in ' + strokes + ' strokes.');
    ball.body.velocity.set(0, 0, 0);
    ball.position.set(cup.position.x, BALL_R, cup.position.z);
    sinkTimer = 1.6;
    aiming = null;
    aimLine.setPoints([START, START]);
    return;
  }
  if (ball.position.y < -0.2 || Math.abs(ball.position.x) > 0.55 || Math.abs(ball.position.z) > 0.55 || ball.position.y > 0.5) {
    strokes += 1;
    info.setText('Strokes: ' + strokes);
    aide.say('Off the table. Ball reset.');
    aiming = null;
    aimLine.setPoints([START, START]);
    resetBall();
  }
});
